    {
      "id": "tree-intro",
      "kind": "content",
      "eyebrow": "基础概念",
      "headline": "什么是树？",
      "lead": "树由节点和边构成，有一个根节点，其余节点分层连接，形成无环的层次结构。",
      "notes": "树可以看作倒置的天然树：根在上，叶在下。与图的关键区别在于树无环且连通。常用术语：根（root）、父节点（parent）、子节点（child）、叶节点（leaf）、子树（subtree）。高度（height）和深度（depth）的定义可能因教材而异，本课采用节点数边数约定：空树高度-1或0？单节点树高度0。现实类比：文件目录是典型的树，根目录包含子目录和文件；公司组织架构中CEO为根，部门为子树。",
      "blocks": [
        {
          "id": "b_terms",
          "type": "list",
          "intent": "定义核心术语：根、边、父子、叶、子树、高度、深度"
        },
        {
          "id": "b_analogy",
          "type": "callout",
          "intent": "用文件目录和公司架构类比，建立直观印象"
        }
      ]
    },
    {
      "id": "binary-traversal",
      "kind": "content",
      "eyebrow": "核心操作",
      "headline": "二叉树与四种遍历",
      "lead": "二叉树每个节点最多有两个子节点，遍历是按某种顺序访问所有节点的系统方法。",
      "notes": "二叉树是树结构的基础，左子和右子严格区分。四种基本遍历：前序（根-左-右）、中序（左-根-右）、后序（左-右-根）、层序（逐层从左到右）。前序用于复制树，中序用于BST得有序序列，后序用于删除树（先删子节点），层序用于广度优先搜索。动画演示可直观展示递归过程。",
      "blocks": [
        {
          "id": "b_traversal_flow",
          "type": "flow",
          "intent": "用流程图展示四种遍历的访问顺序，以具体树为例"
        },
        {
          "id": "b_traversal_use",
          "type": "list",
          "intent": "列出每种遍历的典型应用场景"
        }
      ]
    },
    {
      "id": "recursion-stack",
      "kind": "content",
      "eyebrow": "实现机制",
      "headline": "递归遍历与调用栈",
      "lead": "递归实现遍历代码简洁，但理解函数调用栈的压栈和弹栈过程是掌握递归的关键。",
      "notes": "以前序遍历为例，递归函数调用自身，每次调用将当前节点压栈，返回时弹栈。调用栈的最大深度等于树的高度h，因此空间复杂度O(h)。最坏情况下（退化树）h=n，可能导致栈溢出。迭代版本使用显式栈模拟递归，可避免系统栈限制。",
      "blocks": [
        {
          "id": "b_rec_code",
          "type": "code",
          "intent": "给出前序遍历的递归伪代码，标注递归调用点"
