          "id": "b_rotation_flow",
          "type": "flow",
          "intent": "图示LL、RR、LR、RL四种旋转操作"
        },
        {
          "id": "b_rb_callout",
          "type": "callout",
          "intent": "简要介绍红黑树及其应用"
        }
      ]
    },
    {
      "id": "tree-math",
      "kind": "content",
      "eyebrow": "理论基础",
      "headline": "树的数学性质",
      "lead": "树可用归纳法定义：空树是树；一个根节点连接若干子树构成树。由此可证明诸多性质。",
      "notes": "二叉树第i层最多2^{i-1}个节点，高度为h的二叉树最多2^h-1个节点。证明用数学归纳法：i=1时根节点1个；假设第i层最多2^{i-1}，则第i+1层最多2*2^{i-1}=2^i。高度h的节点总数=Σ_{i=1}^h 2^{i-1}=2^h-1。这些性质是分析树算法复杂度的基础。",
      "blocks": [
        {
          "id": "b_math_formula",
          "type": "formula",
          "intent": "展示节点数与高度的关系式",
          "latex": "N \\leq 2^h - 1 \\quad \\text{且} \\quad h \\geq \\lceil \\log_2(N+1) \\rceil"
        },
        {
          "id": "b_math_proof",
          "type": "list",
          "intent": "列出关键性质并给出归纳证明思路"
        }
      ]
    },
    {
      "id": "implementation",
      "kind": "content",
      "eyebrow": "工程实现",
      "headline": "实现策略：指针与数组",
      "lead": "链表式实现使用节点对象和引用，灵活但内存开销大；数组式实现利用连续内存，适合完全二叉树。",
      "notes": "指针实现：每个节点包含数据和左右子指针，空指针表示无子。数组实现：将完全二叉树按层序存储在数组中，下标i的节点左子在2i+1，右子在2i+2，父在(i-1)//2。二叉堆常用数组实现，因为它是完全二叉树。手动内存管理需注意释放顺序（后序遍历），垃圾回收语言则自动处理。",
      "blocks": [
        {
          "id": "b_impl_compare",
